<div class="thread-panel">
    <div class="thread-header">
        <h5>Thread</h5>
        <button class="close-btn" @onclick="OnClose" aria-label="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <div class="message-header">
                <span class="author">@RootMessage.Author</span>
                <span class="timestamp">@TimeFormatHelper.FormatRelativeTime(RootMessage.SentAt)</span>
            </div>
            <div class="message-content">@RootMessage.Content</div>
        </div>

        <div class="reply-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="author">@reply.Author</span>
                        <span class="timestamp">@TimeFormatHelper.FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        </div>

        <div class="reply-input">
            <textarea @bind="replyText"
                      @bind:event="oninput"
                      placeholder="Reply…"
                      rows="2" />
            <button class="btn btn-primary reply-btn"
                    @onclick="SendReply"
                    disabled="@string.IsNullOrWhiteSpace(replyText)">
                Reply
            </button>
        </div>
    }
</div>

@code {
    [Parameter]
    public Message? RootMessage { get; set; }

    [Parameter]
    public List<Message> Replies { get; set; } = [];

    [Parameter]
    public EventCallback OnClose { get; set; }

    [Parameter]
    public EventCallback<string> OnSendReply { get; set; }

    private string replyText = string.Empty;

    private async Task SendReply()
    {
        if (string.IsNullOrWhiteSpace(replyText)) return;
        var content = replyText;
        replyText = string.Empty;
        await OnSendReply.InvokeAsync(content);
    }
}
"}

