toolArgs.file_text:
.message-bubble {
    padding: 6px 16px;
    position: relative;
    transition: background-color 0.1s;
}

.message-bubble:hover {
    background-color: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 600;
    color: #fff;
    font-size: 0.95rem;
}

.timestamp {
    font-size: 0.75rem;
    color: #72767d;
}

.message-content {
    color: #dcddde;
    font-size: 0.9rem;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border-radius: 12px;
    border: 1px solid #40444b;
    background-color: #2f3136;
    color: #dcddde;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background-color: #40444b;
    border-color: #5865f2;
}

.thread-link {
    display: inline-block;
    margin-top: 4px;
    padding: 2px 8px;
    border: none;
    background: none;
    color: #5865f2;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 16px;
    display: flex;
    gap: 2px;
    background-color: #2f3136;
    border: 1px solid #40444b;
    border-radius: 4px;
    padding: 2px;
    z-index: 10;
}

.action-btn {
    padding: 4px 8px;
    border: none;
    background: none;
    color: #b9bbbe;
    font-size: 0.8rem;
    cursor: pointer;
    border-radius: 3px;
    white-space: nowrap;
}

.action-btn:hover {
    background-color: #40444b;
    color: #fff;
}

.emoji-picker {
    position: absolute;
    top: -12px;
    right: 160px;
    display: flex;
    gap: 2px;
    background-color: #2f3136;
    border: 1px solid #40444b;
    border-radius: 6px;
    padding: 6px;
    z-index: 11;
}

.emoji-btn {
    padding: 4px 6px;
    border: none;
    background: none;
    font-size: 1.2rem;
    cursor: pointer;
    border-radius: 4px;
    line-height: 1;
}

.emoji-btn:hover {
    background-color: #40444b;
}

