toolArgs.file_text:
@using sv_c2eb8817a0c3485c926ec4dfa6a8ee4f.Services

<div class="message-area">
    @if (CurrentChannel is not null)
    {
        <div class="channel-header">
            <h4># @CurrentChannel.Name</h4>
            <p>@CurrentChannel.Description</p>
        </div>

        <div class="message-list">
            @if (HasMoreMessages)
            {
                <div class="load-more">
                    <button class="btn btn-sm btn-outline-secondary"
                            @onclick="OnLoadMore"
                            disabled="@IsLoading">
                        @if (IsLoading)
                        {
                            <span>Loading…</span>
                        }
                        else
                        {
                            <span>↑ Load older messages</span>
                        }
                    </button>
                </div>
            }

            @foreach (var message in Messages)
            {
                <MessageBubble Message="message"
                               ThreadInfo="@GetThreadInfo(message.Id)"
                               OnReplyClicked="() => OnOpenThread.InvokeAsync(message.Id)"
                               OnReactionClicked="emoji => OnReact.InvokeAsync((message.Id, emoji))" />
            }
        </div>

        <div class="message-input">
            <textarea @bind="newMessage"
                      @bind:event="oninput"
                      placeholder="Message #@CurrentChannel.Name"
                      rows="2" />
            <button class="btn btn-primary send-btn"
                    @onclick="SendMessage"
                    disabled="@string.IsNullOrWhiteSpace(newMessage)">
                Send
            </button>
        </div>
    }
    else
    {
        <div class="no-channel">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter]
    public Channel? CurrentChannel { get; set; }

    [Parameter]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = new();

    [Parameter]
    public bool IsLoading { get; set; }

    [Parameter]
    public bool HasMoreMessages { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback<string> OnSendMessage { get; set; }

    [Parameter]
    public EventCallback OnLoadMore { get; set; }

    private string newMessage = string.Empty;

    private ThreadSummary? GetThreadInfo(int messageId) =>
        ThreadSummaries.GetValueOrDefault(messageId);

    private async Task SendMessage()
    {
        if (string.IsNullOrWhiteSpace(newMessage)) return;
        var content = newMessage;
        newMessage = string.Empty;
        await OnSendMessage.InvokeAsync(content);
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #36393f;
    overflow: hidden;
}

.channel-header {
    padding: 12px 16px;
    border-bottom: 1px solid #40444b;
    flex-shrink: 0;
}

.channel-header h4 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
    font-weight: 700;
}

.channel-header p {
    margin: 2px 0 0;
    color: #8e9297;
    font-size: 0.8rem;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.load-more {
    text-align: center;
    padding: 8px;
}

.message-input {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #40444b;
    flex-shrink: 0;
    align-items: flex-end;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    background-color: #40444b;
    color: #dcddde;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
}

.message-input textarea::placeholder {
    color: #72767d;
}

.send-btn {
    padding: 8px 20px;
    border-radius: 8px;
    flex-shrink: 0;
}

.no-channel {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #72767d;
    font-size: 1.1rem;
}

