arguments.file_text:
@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_c2eb8817a0c3485c926ec4dfa6a8ee4f.Components.Chat
@using sv_c2eb8817a0c3485c926ec4dfa6a8ee4f.Services
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container @(isThreadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    SelectedChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea CurrentChannel="selectedChannel"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoading="isLoading"
                 HasMoreMessages="hasMoreMessages"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadOlderMessages" />

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private Channel? selectedChannel;
    private int? selectedChannelId;
    private bool isLoading;
    private bool hasMoreMessages = true;
    private const int PageSize = 30;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = [];
        threadSummaries = new();
        hasMoreMessages = true;
        CloseThread();

        await LoadMessagesAsync();
        _ = ChatService.MarkChannelReadAsync(channelId);
    }

    private async Task LoadMessagesAsync()
    {
        isLoading = true;
        var loaded = await ChatService.GetMessagesAsync(selectedChannelId!.Value, messages.Count, PageSize);

        if (messages.Count == 0)
        {
            messages = loaded;
        }
        else
        {
            messages.InsertRange(0, loaded);
        }

        hasMoreMessages = loaded.Count >= PageSize;
        RebuildThreadSummaries();
        isLoading = false;
    }

    private async Task LoadOlderMessages() => await LoadMessagesAsync();

    private void RebuildThreadSummaries()
    {
        var replyGroups = messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var group in replyGroups)
        {
            var replies = group.ToList();
            threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                replies.Count,
                replies.Max(r => r.SentAt));
        }
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        var thread = await ChatService.GetThreadAsync(messageId);
        threadReplies = thread.Where(m => m.Id != messageId).ToList();
        isThreadOpen = true;

        if (threadReplies.Count > 0)
        {
            threadSummaries[messageId] = new ThreadSummary(
                messageId,
                threadReplies.Count,
                threadReplies.Max(r => r.SentAt));
        }
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        if (selectedChannelId is null) return;
        var refreshed = await ChatService.GetMessagesAsync(selectedChannelId.Value, 0, messages.Count);
        messages = refreshed;
        RebuildThreadSummaries();
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;
        var sent = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(sent);
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannelId is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        messages.Add(reply);

        threadSummaries[threadRootMessage.Id] = new ThreadSummary(
            threadRootMessage.Id,
            threadReplies.Count,
            reply.SentAt);
    }
}

.chat-container {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
    background-color: #36393f;
}

.chat-container.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

